#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int k = 4;
    int suma = 0;
    for (int i = 0; i < k; i++) suma += dane[i];
    int maxSuma = suma, maxPos = 1;
    for (int i = k; i < (int)dane.size(); i++) {
        suma += dane[i] - dane[i - k];
        if (suma > maxSuma) {
            maxSuma = suma;
            maxPos = i - k + 2;
        }
    }
    cout << "Max suma " << k << " kolejnych: " << maxSuma << endl;
    cout << "Poczatek: pozycja " << maxPos << endl;
    return 0;
}
```

